#!/usr/bin/env python3
"""Fill HWPX template placeholders from event_data.json."""

import io
import json
import re
import zipfile
import xml.etree.ElementTree as ET

TEMPLATE_PATH = "/root/event_announcement_template.hwpx"
OUTPUT_PATH = "/root/event_announcement_ready.hwpx"
JSON_PATH = "/root/event_data.json"


def main():
    # Load event data
    with open(JSON_PATH, "r", encoding="utf-8") as f:
        event_data = json.load(f)

    # Read template ZIP
    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        # Build output ZIP
        with zipfile.ZipFile(OUTPUT_PATH, "w", zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)
                if item.filename.endswith(".xml"):
                    text = data.decode("utf-8")

                    # Register namespaces from original XML to preserve prefixes
                    ns_pattern = re.compile(r'xmlns:([^=]+)="([^"]+)"')
                    for prefix, uri in ns_pattern.findall(text):
                        ET.register_namespace(prefix, uri)

                    # Parse XML
                    root = ET.fromstring(text)

                    # Helper to get local tag name
                    def local_name(tag):
                        return tag.split("}")[-1] if tag.startswith("{") else tag

                    # Determine fully-qualified tags
                    para_tag = None
                    t_tag = None
                    run_tag = None
                    for elem in root.iter():
                        ln = local_name(elem.tag)
                        if ln == "p" and para_tag is None:
                            para_tag = elem.tag
                        if ln == "t" and t_tag is None:
                            t_tag = elem.tag
                        if ln == "run" and run_tag is None:
                            run_tag = elem.tag
                        if para_tag and t_tag and run_tag:
                            break

                    if para_tag is None or t_tag is None:
                        # Nothing to replace here
                        zout.writestr(item, data)
                        continue

                    # Process each paragraph
                    for para in list(root.iter(para_tag)):
                        # Collect all text runs (hp:t) in document order within this paragraph
                        runs = [r for r in para.iter(t_tag)]
                        if not runs:
                            continue

                        original = "".join(r.text or "" for r in runs)
                        replaced = original
                        for key, value in event_data.items():
                            replaced = replaced.replace(f"{{{key}}}", value)

                        if replaced == original:
                            continue

                        # Verify no placeholders remain
                        if "{{" in replaced:
                            raise ValueError(f"Unreplaced placeholder remains: {replaced}")

                        # Set first text run to full replaced string
                        runs[0].text = replaced

                        # Remove subsequent text runs and their parent runs if empty
                        for r in runs[1:]:
                            parent_map = {c: p for p in root.iter() for c in p}
                            # Build parent map for the whole tree is expensive; use direct traversal
                            pass

                        # Better: build a small parent map for para subtree
                        parent_map = {}
                        for p_elem in para.iter():
                            for child in p_elem:
                                parent_map[child] = p_elem

                        for r in runs[1:]:
                            parent = parent_map.get(r)
                            if parent is not None:
                                parent.remove(r)
                                # If parent is a run and now has no children, remove it from paragraph
                                if parent.tag == run_tag and len(list(parent)) == 0:
                                    para.remove(parent)
                            else:
                                try:
                                    para.remove(r)
                                except ValueError:
                                    pass

                        # Remove all lineSegArray children regardless of namespace
                        for child in list(para):
                            if local_name(child.tag).lower() == "linesegarray":
                                para.remove(child)

                    # Re-serialize with XML declaration
                    xml_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
                    zout.writestr(item, xml_bytes)
                else:
                    zout.writestr(item, data)

    # Verify no placeholders remain
    with zipfile.ZipFile(OUTPUT_PATH, "r") as zout:
        for name in zout.namelist():
            if name.endswith(".xml"):
                content = zout.read(name).decode("utf-8")
                if "{{" in content:
                    raise ValueError(f"Placeholder remains in {name}")

    print("Template filled successfully.")
    print(f"Output written to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()

